/* ============================================================
   5. 消息气泡 (Bubbles)
   ============================================================ */

/* ---------- 变量 ---------- */
:root {
  --bubble-me-bg: #d4e4ff;
  --bubble-me-color: #0a1a3a;
  --bubble-me-radius: 22px 22px 22px 22px;
  --bubble-me-shadow: 0 2px 10px rgba(60, 120, 255, 0.12);
  --bubble-me-border: none;

  --bubble-them-bg: #ffffff;
  --bubble-them-color: #0a1a3a;
  --bubble-them-radius: 22px 22px 22px 22px;
  --bubble-them-shadow: 0 2px 12px rgba(0, 0, 0, 0.05);
  --bubble-them-border: none;
}

/* ---------- 我方气泡 ---------- */
.bubble-me-custom {
  position: relative !important;
  overflow: visible !important;
}
.bubble-me-custom::after {
  content: "";
  position: absolute;
  right: -6px;
  bottom: 12px;
  width: 14px;
  height: 14px;
  background: var(--bubble-me-bg);
  clip-path: polygon(0 0, 100% 100%, 0 100%);
  border-radius: 0 0 4px 0;
}
.bubble-me-custom::before {
  content: "";
  position: absolute;
  left: -10px;
  bottom: -18px;
  width: 40px;
  height: 40px;
  background-image: url('https://nos.netease.com/ysf/1b80b9979633b7db7d1ede7ee6e36e82.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  pointer-events: none;
  z-index: 2;
}

/* ---------- 对方气泡 ---------- */
.bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
}
.bubble-them-custom::after {
  content: "";
  position: absolute;
  left: -6px;
  bottom: 12px;
  width: 14px;
  height: 14px;
  background: var(--bubble-them-bg);
  clip-path: polygon(100% 0, 0 100%, 100% 100%);
  border-radius: 0 0 0 4px;
}
.bubble-them-custom::before {
  content: "";
  position: absolute;
  right: -10px;
  bottom: -18px;
  width: 40px;
  height: 40px;
  background-image: url('https://nos.netease.com/ysf/1b80b9979633b7db7d1ede7ee6e36e82.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  pointer-events: none;
  z-index: 2;
}

/* ---------- 夜间 ---------- */
@media (prefers-color-scheme: dark) {
  .bubble-me-custom {
    background: #0a1225 !important;
    color: #80b8ff !important;
    border: none !important;
    box-shadow: none !important;
  }
  .bubble-me-custom::after {
    background: #0a1225 !important;
  }
  .bubble-me-custom::before {
    background-image: url('https://nos.netease.com/ysf/29947a33736b6c46c7fa029ce5108ff0.png') !important;
    width: 28px !important;
    height: 28px !important;
    left: -10px !important;
    bottom: -10px !important;
  }

  .bubble-them-custom {
    background: #0a1225 !important;
    color: #b0c8f0 !important;
    border: none !important;
    box-shadow: none !important;
  }
  .bubble-them-custom::after {
    background: #0a1225 !important;
  }
  .bubble-them-custom::before {
    background-image: url('https://nos.netease.com/ysf/29947a33736b6c46c7fa029ce5108ff0.png') !important;
    width: 28px !important;
    height: 28px !important;
    right: -10px !important;
    bottom: -10px !important;
  }
}

/* ============================================================
   6. 头像 (Avatar)
   ============================================================ */
.msg-avatar-container {
