  --narration-border: 1px solid rgba(74, 144, 217, 0.15);
  --narration-shadow: none;
  --narration-text-shadow: none;
  --narration-text-align: center;
  --narration-opacity: 1;
  --narration-backdrop: none;
  --narration-max-width: 100%;
}

@media (prefers-color-scheme: dark) {
