  border-radius: 14px !important;
  border: 1px solid rgba(74, 144, 217, 0.1) !important;
  box-shadow: 0 1px 4px rgba(74, 144, 217, 0.06) !important;
  font-style: normal !important;
  font-weight: 400 !important;
  text-align: center !important;
  display: inline-block !important;
}

@media (prefers-color-scheme: dark) {
  .nuo-pat-msg {
    background: #0e1a2a !important;
    color: #aaccee !important;
    border: 1px solid rgba(255, 255, 255, 0.06) !important;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3) !important;
  }
}

/* ============================================================
   20. 更多菜单 (More Options)
   ============================================================ */

/* ---------- 日间 ---------- */
.more-options-popup {
  background: rgba(235, 245, 255, 0.92) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  box-shadow: 0 10px 40px rgba(74, 144, 217, 0.12) !important;
  border: 1px solid rgba(74, 144, 217, 0.1) !important;
  border-radius: 18px !important;
}

.more-options-item-row span,
.more-options-item-row svg {
  color: #1a1a1a !important;
}
.more-options-item-row:hover {
  background: rgba(74, 144, 217, 0.08) !important;
  border-radius: 8px !important;
}
.more-options-item-row {
  border-bottom: 1px solid rgba(74, 144, 217, 0.06) !important;
}
.more-options-item-row:last-child {
  border-bottom: none !important;
}

/* ---------- 夜间 ---------- */
@media (prefers-color-scheme: dark) {
  .more-options-popup {
    background: #0e1a2a !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.6) !important;
    border: 1px solid rgba(74, 144, 217, 0.15) !important;
  }
  .more-options-item-row span,
  .more-options-item-row svg {
    color: #7ab0e8 !important;
  }
  .more-options-item-row:hover {
    background: rgba(74, 144, 217, 0.1) !important;
  }
  .more-options-item-row {
    border-bottom: 1px solid rgba(74, 144, 217, 0.08) !important;
  }
}

/* ============================================================
   21. 上下文菜单 (Context Menu)
   ============================================================ */

/* ---------- 日间 ---------- */
.ig-context-menu {
  background: rgba(235, 245, 255, 0.96) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  border-radius: 16px !important;
  box-shadow: 0 8px 30px rgba(74, 144, 217, 0.12) !important;
  border: 1px solid rgba(74, 144, 217, 0.1) !important;
  padding: 6px 0 !important;
  min-width: 160px !important;
}

.ig-menu-item {
  color: #1a1a1a !important;
  padding: 10px 16px !important;
  font-size: 14px !important;
  transition: background 0.15s ease !important;
}
.ig-menu-item:hover {
  background: rgba(74, 144, 217, 0.08) !important;
}
.ig-context-menu .divider {
  border-top: 1px solid rgba(74, 144, 217, 0.08) !important;
  margin: 4px 12px !important;
}

/* ========== 底部输入框胶囊｜夜间模式改成深灰色 ========== */
@media (prefers-color-scheme: dark) {
  /* 输入框外层整体背景（底部条） */
  .chat-input-area {
    background-color: #121218 !important;
  }
  /* 真正的白色胶囊盒子，修改这个才会变 */
  .chat-input-area > div {
    background-color: #2a2d34 !important;
  }
  /* 输入框内文字、placeholder适配深色 */
  .chat-input-area textarea,
  .chat-input-area [contenteditable] {
    color: #e2e8f0 !important;
  }
  .chat-input-area ::placeholder {
    color: #8892a0 !important;
  }
}
@media (prefers-color-scheme: dark) {
  /* 直接匹配底部那个白色圆角胶囊 */
  body > div:last-child div[class*="input-box"] {
    background: #2a2d34 !important;
    background-image: none !important;
  }
  body > div:last-child [contenteditable] {
    color:#e2e8f0 !important;
  }
  body > div:last-child [contenteditable]::placeholder {
    color:#8892a0 !important;
  }
}
